return new BrokerSession({
  repository: pr.repository,
  prNumber: pr.number,
  headSha: pr.headSha,
  token: "", // nothing to leak: both GitHub paths below are injected
  forbiddenSecrets: [capability],
  executeRead: async (args) => {
    if (args[0] === "pr" && args[1] === "diff") return ok(diff);
    if (args[0] === "pr" && args[1] === "view") return ok(JSON.stringify(pick(pr.view, jsonFields(args))));
    if (args[0] === "api" && /\/pulls\/\d+\/files/.test(args[1] ?? "")) return ok(JSON.stringify(pr.files));
    if (args[0] === "api" && /\/(pulls|issues)\/\d+\/(reviews|comments)/.test(args[1] ?? "")) return ok("[]");
    return { exitCode: 1, stdout: "", stderr: "not in the replay pack" };
  },
  // publications are recorded, never posted
  api: recordingApi(async (review) => {
    published.push(review);
    await writeFile(join(outputDir, "publication.json"), `${JSON.stringify(published, null, 2)}\n`);
    return { id: published.length };
  }),
});
